registerPage('settings','Settings',async()=>{
 setPill(null);const [c,worker,receiptSummary]=await Promise.all([api('/config'),api('/cancellations/status'),api('/receipts').catch(()=>({}))]);applyComfort(c);
 const labels={recent:'Recent activity',upcoming:'Upcoming payments',cashflow:'Cash flow',goals:'Goals'};const order=[...(c.home_cards||[]),...Object.keys(labels).filter(k=>!c.home_cards?.includes(k))];
 return `<div class="page-intro"><div><h2>A space that feels like you.</h2><p>A little personalization. Only as much as you want.</p></div></div><div class="settings-grid"><section class="card"><h3>Look & feel</h3><div class="setting-row"><label for="setting-palette">Color direction</label><select id="setting-palette" class="input" data-pref="palette"><option value="paper" ${c.palette==='paper'?'selected':''}>Warm newsprint</option><option value="colorful" ${c.palette!=='paper'?'selected':''}>Colorful</option></select></div><div class="setting-row"><span>Your font</span>${action('page','Compare three styles →','typography','link-button')}</div><div class="setting-row"><label for="setting-theme">Appearance</label><select id="setting-theme" class="input" data-pref="theme">${['system','light','dark'].map(v=>`<option value="${v}" ${c.theme===v?'selected':''}>${v==='system'?'Match my device':v==='light'?'Light':'Dark'}</option>`).join('')}</select></div><div class="setting-row"><label for="setting-density">Spacing</label><select id="setting-density" class="input" data-pref="density"><option value="comfortable" ${c.density==='comfortable'?'selected':''}>Room to breathe</option><option value="compact" ${c.density==='compact'?'selected':''}>A little closer</option></select></div><p class="small muted">Your accent color</p><div class="swatches">${Object.entries({blue:'#7596aa',sage:'#759e8c',plum:'#a28eaf',clay:'#bd9683'}).map(([k,v])=>`<button class="swatch ${c.accent===k?'selected':''}" style="background:${v}" data-action="accent" data-id="${k}" aria-label="${k} accent" aria-pressed="${c.accent===k}"></button>`).join('')}</div><p class="quiet-note">Changes save across your devices.</p></section><section class="card"><h3>Your home dashboard</h3><p class="small muted">Choose what you see. Move your favorites up.</p>${order.map((k,n)=>`<div class="layout-item"><input type="checkbox" id="card-${k}" data-home-card="${k}" ${c.home_cards?.includes(k)?'checked':''}><label for="card-${k}" style="flex:1">${labels[k]}</label><button data-action="move-card" data-id="${k}" aria-label="Move ${labels[k]} up" ${n===0?'disabled':''}>↑</button></div>`).join('')}</section><section class="card"><h3>The everyday details</h3><form data-form="preferences">${field('owner_name','What should we call you?',c.owner_name,'text','maxlength="50" placeholder="Your first name"')}${field('monthly_spending_target','Monthly spending plan',c.monthly_spending_target||'','number','min="0" step="1" placeholder="Optional"')}<p class="form-help">Your total spending target, including subscriptions. Leave empty to focus on actual spending.</p>${field('tax_rate_business','Business tax set-aside (%)',Number(c.tax_rate_business)*100,'number','min="0" max="100" step="0.1"')}<p class="auth-error" role="alert" data-form-error></p><button type="submit" class="btn">Save preferences</button></form></section>${receiptSettingsCard(receiptSummary,c)}<section class="card"><h3>Cancellation assistant</h3><div class="status-panel">${esc(worker.message||worker.reason||(worker.ready?'Your local worker is ready.':'Finish Codex setup on your home lab to enable cancellation requests.'))}</div><p class="quiet-note">Uses your existing Codex sign-in and the configured Luna model. Provider sign-ins stay in a separate browser on your home lab.</p>${action('page','View subscriptions →','subscriptions','link-button')}<details class="disclosure"><summary>Bank connection settings</summary><p class="quiet-note">${c.plaid_configured?'Plaid credentials are saved. Leave the fields empty to keep them.':'Add the credentials from your Plaid dashboard to enable bank linking.'}</p><form data-form="plaid">${field('plaid_client_id','Plaid client ID','','text','autocomplete="off"')}${field('plaid_secret','Plaid secret','','password','autocomplete="new-password"')}<label class="fld" for="f-plaid_env">Environment</label><select class="input" name="plaid_env" id="f-plaid_env"><option value="production" ${c.plaid_env==='production'?'selected':''}>Production · real banks</option><option value="sandbox" ${c.plaid_env==='sandbox'?'selected':''}>Sandbox · test banks</option></select>${field('plaid_redirect_uri','Registered HTTPS redirect URL',c.plaid_redirect_uri,'url','placeholder="https://your-private-ledger/"')}${field('sync_interval_minutes','Sync interval (minutes)',c.sync_interval_minutes,'number','min="30" max="1440"')}<p class="auth-error" role="alert" data-form-error></p><button class="btn" type="submit">Save bank settings</button></form></details></section><section class="card"><h3>Your data</h3><p class="small muted">Your Ledger lives on your home lab. Keep a backup somewhere separate.</p><div class="row">${action('export','Export transactions')}${!c.demo?action('logout','Lock Ledger'):''}</div><details class="disclosure"><summary>Sample data & reset</summary><p class="quiet-note">Sample data is for exploring before linking real accounts. Reset permanently clears financial records; your login remains.</p><div class="row">${action('seed','Load samples')}${action('reset','Reset financial data','','btn btn-danger')}</div></details></section></div>`;
});

